from aichat_sdk.mcp_tool.server import mcp

logger = logging.getLogger("aichat_sdk")

MUSIC_DIR = Path(__file__).resolve().parents[0] / "music"
MUSIC_LIBRARY = {p.stem: p for p in sorted(MUSIC_DIR.iterdir()) if p.suffix.lower() == ".jsonl"}


def _match_song(song: str, names: list[str]) -> str | None:
    if not song:
        return random.choice(names)
    for name in names:
        if song == name or song in name or name in song:
            return name
    matches = difflib.get_close_matches(song, names, n=1, cutoff=0.5)
    return matches[0] if matches else None


@mcp.tool()
def play_music(
    song: str = Field(
        default="",
        description="用户指定的歌名；未指定歌名或要求随便播放时传空字符串",
    ),
) -> dict:
    """播放本地曲库中的音乐。当用户明确要求播放音乐、点歌、想听歌、放一首或来一首时，
    必须调用此工具，禁止只回复“好的”“为你播放”等口头承诺而不调用。只有工具返回成功后，
    才能简短告诉用户即将播放；未指定歌名时也要调用，song 传空字符串。"""

    if not MUSIC_LIBRARY:
        return {"isError": True, "error": "本地曲库为空，无法播放，请如实告知用户"}
    name = _match_song(song.strip(), list(MUSIC_LIBRARY))
    if name is None:
        return {"isError": True, "error": f"没有找到歌曲《{song}》，可选歌单：{'、'.join(MUSIC_LIBRARY)}"}
    return {
        "isError": False,
        "mcp": "music_stream_play",
        "song": name,
    }


# 音频流走不了标准 MCP CallTool 序列化，宿主进程 import 同一注册表后经 stream_mcp_tool 直调 tool.fn
@mcp.tool(meta={"aichat_sdk": {"internal": True}})
async def music_stream_play(song: str) -> AsyncIterator[dict[str, Any]]:
    path = MUSIC_LIBRARY[song]
    logger.info(f"[music] play: {path}")
    jsonl = Path(path).with_suffix(".jsonl")
    for line in jsonl.read_text(encoding="utf-8").splitlines():
        record = json.loads(line)
        if record.get("text"):
            yield {"type": "lyric", "data": record["text"]}
        elif "audio" in record:
            for b64_packet in record["audio"]:
                yield {"type": "audio", "data": base64.b64decode(b64_packet)}

    yield {"type": "audio_finish", "data": ""}
